package com.skyglass.catalog

import java.io.BufferedInputStream
import java.io.ByteArrayOutputStream
import java.io.DataInputStream
import java.io.InputStream
import java.util.zip.InflaterInputStream
import kotlin.math.floor

/**
 * The bundled light-pollution map (`light_pollution.bin`): the modelled zenith sky brightness on a
 * clear, moonless night, in mag/arcsec² (what a Sky Quality Meter reads; larger is darker), on
 * 0.05° cells from 75° N to 65° S. Generated by `tools/light_pollution/gen_light_pollution.py` from
 * VIIRS satellite night lights; the file's header documents the format.
 */
object LightPollution {

    /** The grid's geometry and quantisation, from the header's `grid` line (see the file header). */
    data class Grid(
        val rows: Int,
        val cols: Int,
        val lat0: Double,
        val lon0: Double,
        val step: Double,
        val qMin: Double,
        val qStep: Double,
    )

    /**
     * The sky brightness at ([latDeg], [lonDeg]), interpolated between the four nearest cell centres
     * (wrapping in longitude), or null outside the map. Reads [input] only down to the rows it needs,
     * so the 20 MB grid is never held in memory. Blocking; does not close [input].
     */
    fun skyBrightness(input: InputStream, latDeg: Double, lonDeg: Double): Double? {
        val buffered = BufferedInputStream(input)
        val grid = parseHeader(readHeader(buffered))
        val y = (grid.lat0 - latDeg) / grid.step
        if (y < -0.5 || y > grid.rows - 0.5) return null
        val row = floor(y).toInt().coerceIn(0, grid.rows - 2)
        val fy = (y - row).coerceIn(0.0, 1.0)
        val x = ((lonDeg - grid.lon0) / grid.step).mod(grid.cols.toDouble())
        val col = floor(x).toInt() % grid.cols
        val fx = x - floor(x)
        val nextCol = (col + 1) % grid.cols

        val data = DataInputStream(InflaterInputStream(buffered))
        var above = ByteArray(grid.cols)
        var current = ByteArray(grid.cols)
        for (r in 0..row + 1) {
            data.readFully(current)
            // Each byte is stored as its difference from the byte above it, mod 256.
            if (r > 0) for (c in 0 until grid.cols) current[c] = (current[c] + above[c]).toByte()
            val swap = above
            above = current
            current = swap
        }
        // `above` now holds row + 1 and `current` holds row.
        fun value(bytes: ByteArray, c: Int) = grid.qMin + (bytes[c].toInt() and 0xFF) * grid.qStep
        val top = value(current, col) * (1 - fx) + value(current, nextCol) * fx
        val bottom = value(above, col) * (1 - fx) + value(above, nextCol) * fx
        return top * (1 - fy) + bottom * fy
    }

    /** The ASCII header: everything before the first blank line. */
    private fun readHeader(input: InputStream): String {
        val bytes = ByteArrayOutputStream()
        var previous = -1
        while (true) {
            val b = input.read()
            require(b >= 0) { "Light pollution file has no blank line after its header" }
            if (b == '\n'.code && previous == '\n'.code) break
            bytes.write(b)
            previous = b
            require(bytes.size() < MAX_HEADER_BYTES) { "Light pollution header is too long" }
        }
        return bytes.toString(Charsets.US_ASCII.name())
    }

    /** The `grid rows cols lat0 lon0 step qmin qstep` line; `#` lines are comments. */
    internal fun parseHeader(header: String): Grid {
        val fields = header.lineSequence().map { it.trim() }.firstOrNull { it.startsWith("grid ") }
            ?.split(Regex("\\s+"))
        require(fields != null && fields.size == 8) { "Light pollution header has no valid grid line" }
        val grid = Grid(
            rows = fields[1].toInt(),
            cols = fields[2].toInt(),
            lat0 = fields[3].toDouble(),
            lon0 = fields[4].toDouble(),
            step = fields[5].toDouble(),
            qMin = fields[6].toDouble(),
            qStep = fields[7].toDouble(),
        )
        require(grid.rows >= 2 && grid.cols >= 2 && grid.step > 0 && grid.qStep > 0) { "Bad light pollution grid: $grid" }
        return grid
    }

    private const val MAX_HEADER_BYTES = 8192
}
